INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-045', 'SW', 'P3', 'CLOSED-FIXED', 'governance', NULL, 'resolve-candidate COULD NOT WRITE suggested_slug, so a REHOME disposition could not say where the candidate belongs. Found by an independent adversarial pass on batch 20: candidate 117 was re-described as rehomed to stair-ramp-threshold-biomechanics-accessibility while its typed suggested_slug still named accessible-circulation-geometry, the slug it was found under -- the prose and the only joinable column disagreeing. CLAUDE.md section 4: a column the CLI cannot reach is a coverage bug, not a licence for hand SQL. FIXED IN THE SAME BATCH: resolve-candidate takes --suggested-slug with --disposition REHOME only, validates it against slugs, and records the replaced value in the notes tail. Derive whether any REHOME row still points back at its origin: select candidate_id, found_under_slug, suggested_slug from search_candidates where disposition=''REHOME''.', '2026-09-25 06:10', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 06:10', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-046', 'SW', 'P2', 'CLOSED-FIXED', 'governance', NULL, 'NO VERB COULD ATTACH AN ADMISSION TO AN EXISTING SEARCH. search_admissions is the one carrier of which search admitted a source, and its only writer was log-search --admitted-ref-id, which attaches an admission only to a search logged in the same call. A source admitted in a later batch from a staged candidate therefore could not point back at the search that surfaced it, although integrity check S01 states that the surfacing search and the admitting search are the same event (batch 17''s candidates 107/108 on exec 77 are the precedent). research_protocol_audit then reported REF-01007 and REF-01008 as admitted by no search. Batch 20 first read that as the audit''s case (b) and wrote no edge; an independent adversarial pass sustained it as case (a) plus a writer gap. FIXED IN THE SAME BATCH: db.py link-admission writes the edge ONLY when a search_candidates row already records both ends (that candidate''s exec_id and resolved_ref_id, disposition ADMITTED) and refuses otherwise, so it restates a recorded fact and cannot attribute a source to an arbitrary search. Applied to (91, REF-01007) and (90, REF-01008).', '2026-09-25 06:10', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 06:10', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-047', 'SW', 'P3', 'CLOSED-FIXED', 'governance', NULL, 'TWO OWNER RULINGS OF 2026-09-25 HAD NO WRITER TO APPLY THEM. (1) Re-grading an R13 population match: add-population-match deliberately allows a SECOND row so that a dissent reads as a contest, but a ruling is not a dissent, and nothing could move an existing grade. (2) Narrowing a term''s definition: nothing could write `terms` after add-term. Both are coverage bugs under CLAUDE.md section 4. FIXED IN THE SAME BATCH: amend-population-match (grade checked against the column''s own CHECK; the replaced grade and the reason appended to mismatch_note) and amend-term (definition or scope_note only -- canonical_en is a vocabulary decision -- with the replaced text and the reason appended to scope_note, the row''s only free-text column).', '2026-09-25 06:10', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 06:10', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-048', 'AUDT', 'P2', 'OPEN', 'governance', NULL, 'v_value_independence COUNTS ABSENCES AS INDEPENDENT ROOTS. The view counts DISTINCT COALESCE(root_ref_id, root_id) over rows whose root_type is measurement_primary, participatory_finding or derived_calculation, and never looks at claim_type. A row with claim_type ''absent'' asserts that its source states NO value, yet it adds a root to the parameter''s independent-root count exactly as a measured value does. Batch 20 made it worse: REF-01007 (extraction 59, absent-confirmed) is a new root that measures nothing on the parameter. Raised by an independent adversarial pass (finding #9) and WITHHELD from repair in batch 20 pending an owner decision on how independence should be counted; the view is NOT redefined here. Derive the absence-only roots rather than trusting any list: select coalesce(root_ref_id, root_id) root, count(*) n from source_value_extractions where parameter_id=3 and root_type in (''measurement_primary'',''participatory_finding'',''derived_calculation'') group by root having sum(claim_type <> ''absent'') = 0. Compare select * from v_value_independence where parameter_id=3.', '2026-09-25 06:10', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 06:10', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-049', 'RP', 'P2', 'OPEN', 'multilingual-research', NULL, 'BATCH 20''s R1 (Co-1 / T2) LEG WAS A THIN DISCHARGE OF R1, NOT A FULL ONE. It ran three queries (exec 92-94): English only, one biomedical full-text index (Europe PMC), no DPO or disability-organisation channel, no non-English vocabulary, no grey-literature route. research_batch_dod R1 passes when Co-1-targeted searches exist, which is why the gate was green; an independent adversarial pass (finding #20) sustained that the leg did not do what R1 exists for -- ''Co-1 / T2 / Co-2 pass FIRST'', co-primary with T1 under CRPD 4.3. FOR A FUTURE BATCH, not a repair: a Co-1 pass on ramp gradient that reaches DPO and user-led outputs in more than one language and more than one kind of index. Candidate 126 (Mactaggart 2024, a participatory audit staged by this leg) is the strongest lead it produced.', '2026-09-25 06:10', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 06:10', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', NULL, NULL, NULL, NULL, NULL);
UPDATE "gaps" SET "description" = 'TERM ADJUDICATION HAS NEVER RUN, AND NOTHING SAYS SO. Harvest at evidence, adjudicate at judgment (owner 2026-08-27, overruling DR-2026-08-24 section 2.4). The harvest half works -- derive it with: select count(*) from observed_terms. The adjudication half has produced nothing at all -- select count(*) from term_adjudications -- and db.py adjudicate-term exists, so this is a backlog, not a missing capability. CLAUDE.md section 6 says outright that zero links AFTER judgment is a defect, and no gap, no check and none of the five documents a cold-starting session reads names this. Found by walking the spine forward from this batch''s two admissions: research -> evidence walks, evidence -> judgment stops here with no marker. WHAT WOULD CLOSE IT: adjudicate the harvested terms, or record why the backlog is deliberate. WHAT WOULD MAKE IT VISIBLE MEANWHILE: a check asserting that observed_terms older than N batches have an adjudication, which is the general form of the same question. || CORRECTED 2026-09-25: BATCH 20: ADJUDICATION HAS RUN OVER THE WHOLE BACKLOG, AND THIS GAP STAYS OPEN ONLY FOR WHAT WAS DEFERRED WITH A REASON. Every observed_terms row now carries a term_adjudications row, each with an observation-specific rationale. DERIVE THE COUNTS, DO NOT QUOTE THEM: select outcome, count(*) from term_adjudications group by outcome; and the residual backlog: select count(*) from observed_terms o where not exists (select 1 from term_adjudications a where a.observation_id=o.observation_id). SIX TERMS WERE MINTED through add-term (NAMES-NEW), each warranted by the corpus rather than coined: ramp (the element; TERM-001 is its slope), level difference, ramp run length, intermediate landing, ramp usability (the outcome side: completion, Borg effort, discomfort and difficulty ratings are adjudicated to it as measures), and accessibility audit -- derive them with select term_id, canonical_en from terms where created_by_session like ''%batch-20%''. THE DEFERRALS GROUP INTO FIVE OPEN QUESTIONS, and each is a decision about the vocabulary, not about a phrase: (1) RAMP VERSUS ROUTE GRADIENT -- TERM-001 is defined on ramps, four observations measure path and trail slopes, and extraction 49 already files REF-01003''s path slopes on parameter 3; this is a scoping question for parameter 3 itself and belongs to the batch that re-determines it. (2) ACTIVITY PHRASES (ascending slopes, slope propulsion) -- term rows or ICF d4 links; the only activity-shaped terms are the functional-axis rows the owner called a bad coinage on 2026-08-18. (3) CONCEPTS HELD AS COLUMN VOCABULARIES (self-propulsion as device_class, CBPR as co1_source_type) -- rule 5 forbids a second home as a term, and NOT-OURS would be false. (4) THE DESIGN CASE (marginal population) -- the project''s answer is the owner''s most-accommodating rule, a doctrine, which a term would smuggle into the vocabulary. (5) SINGLE-SOURCE OR BACK-TRANSLATION RISKS (accessible route from a Japanese statute, site path, dwelling setting, a named housing standard, universal accessibility from a title, ramp incident, exterior ramp threshold) -- each needs a source that states the concept in its own words. PREDICTION TESTED: prior P5a (a writer or vocabulary defect surfaces before the verb runs cleanly) was NOT borne out -- adjudicate-term and add-term ran cleanly on every row. || CORRECTED 2026-09-25: CORRECTION TO THE BATCH-20 NOTE ABOVE, SAME BATCH. It groups the deferrals into five questions, and the groups as listed account for all but one: observation 54 (''walking and reaching limitations'', REF-01005''s title) is a FUNCTIONAL-LIMITATION phrase whose only terms are the functional-axis rows TERM-031 and TERM-041 -- not an activity phrase, which is what group (2) names. It belongs with group (2) under a wider heading: phrases whose only possible targets are the functional-axis terms the owner called a bad coinage on 2026-08-18. Derive the membership rather than trusting either note: select o.observation_id, o.surface_form from observed_terms o join term_adjudications a using (observation_id) where a.outcome=''DEFERRED'' order by 1. || CORRECTED 2026-09-25: OWNER RULING 2026-09-25, AND WHAT IT DID NOT SETTLE. TERM-089 (''ramp'') is narrowed to exclude the running slope of paths, walkways and trails, so it no longer pre-decides group (1), the ramp-versus-route question, which stays OPEN here. THREE FURTHER POINTS that an independent adversarial pass raised on batch 20''s minted terms (finding #14) are NOT resolved by that ruling and are open on this gap: (a) TERM-094 (''accessibility audit'') has a scope note that states as a universal -- ''An audit measures COMPLIANCE with a yardstick, never what the yardstick should be'' -- what is one testable prior (batch 20''s P1b) drawn from two sources; (b) TERM-093 (''ramp usability'') is defined as ''the outcome a ramp gradient is judged against'' and its scope note adjudicates the measures to it as operationalisations, which forecloses a separate term for the acceptability CRITERION as distinct from the measure; (c) TERM-092''s scope note says ''It bounds TERM ramp run length from above'' -- a dangling reference with no term id. Each is a vocabulary decision for the owner, not a wording fix, and none was edited.', "updated_at" = '2026-09-25 06:10' WHERE "gap_id" = 'GAP-033';
UPDATE "gaps" SET "description" = 'GAP-028 IS ANSWERED, AND THE ANSWER IS THAT 1:12 WAS MEASURED AND FOUND WANTING BEFORE IT WAS ADOPTED. GAP-028 asked whether the 1:12 threshold is anchored in measurement. REF-01005 (Steinfeld, Schroeder and Bishop 1979, HUD-PDR 397, ERIC ED184280, full text retrieved and persisted this batch) settles it. (1) THE MEASUREMENT EXISTS. A purpose-built adjustable 40-foot ramp, 124 disabled participants, slope stepped 1:12 then 1:16 then 1:20, success judged on distance, time and pulse recovery to within ten beats of resting. (2) IT FOUND 1:12 INADEQUATE: almost half the wheelchair users could not negotiate the full length at 1:12 and about a third could not travel even 5 feet; every wheelchair user completed 40 feet at 1:20, though only three reached that trial. (3) THE STUDY WAS COMMISSIONED TO IMPROVE THE VERY STANDARD THAT CARRIES 1:12 — its Foreword says the six-report series was sponsored to make buildings accessible "through improving the American National Standards Institute A117 standard". (4) ITS OWN RECOMMENDATION TABLE RESTS PARTLY ON OTHERS: Table 13 footnote c reads "Based on research of others (Templer, 1977 and Walter, 1971)", so the chain has three nodes and this project holds one. (5) WALTER 1971 AND STEINFELD 1979 CONVERGE at 1:16 over 20 feet for at least 95 percent of wheelchair users, per page 163 — held on Steinfeld testimony alone, so it is ONE document counted once until Walter is retrieved. WHAT THIS DOES NOT DO: it does not supply a current anchor. Owner ruling 2026-09-18 places 1979 work as historical grounding rather than a present standard, so REF-01005 is admitted T3 grey and parameter 3 x MOB stays undetermined. WHAT IS NOW OWED: retrieve Walter 1971 (candidate 109, record verified) and Templer 1977 (candidate 115) — the two remaining nodes of the chain. Derive the state rather than quoting this: select disposition, title from search_candidates where candidate_id in (109,110,111,115). || CORRECTED 2026-09-20: BATCH 19 WORKED BOTH OWED NODES. NEITHER IS RETRIEVED; BOTH ARE MATERIALLY NARROWED, AND ONE CLAUSE OF THIS GAP NEEDS QUALIFYING. (1) THE QUALIFICATION, WHICH RUNS AGAINST THIS GAP''S OWN FRAMING: clause (4) says Table 13 ''rests partly on others'' and treats Templer and Walter as the two remaining nodes of THE 1:12 CHAIN. The footnote marker c appears on the 1:8 and 1:10 rows ONLY, not on 1:12 or 1:16 -- derive it at pypdf page index 56, and note it is coherent rather than noise because Table 12 shows the study tested exactly 1:12, 1:16 and 1:20, so the warranted bands are precisely the two OUTSIDE its tested range. On that reading the named warrant covers the permissive end of the table and the 1:12 and 1:16 rows rest on Steinfeld''s own data, which means Templer and Walter are not nodes of the 1:12 chain at all. Recorded as extraction 56 and held as A READING, NOT AS SETTLED: these are single characters on a damaged scan and a cleaner copy of page 57 decides it. (2) TEMPLER: ''Templer, 1977'' does not resolve to any indexed item, and John A. Templer''s corpus is stairs end to end -- 1974 dissertation (the one this bibliography actually lists), 1978 NBS IR 78-1554 ''An analysis of the behavior of stair users'', 1984 ''The Forgiving Stair'', 1989 ''The Soft Stair''. Four items, fifteen years, no ramp study, nothing dated 1977. ERIC author:Templer returns 33 records with none architectural and ERIC Templer+stairs returns 0, which is a well-formed negative rather than a query-shape failure. Candidate 115''s title over-claimed it as ''the ramp-slope research'' and is corrected. Candidate 117 stages the 1978 NBS report as the nearest RESOLVABLE neighbour, explicitly without claiming it is the referent. (3) WALTER: the year 1971 is now corroborated by a Library of Congress MARC record, which matters because this bibliography''s own year digits for Walter are OCR-damaged and unreadable. The route this gap and candidate 109 both named next -- Jisc Library Hub Discover -- IS CLOSED: HTTP 403 behind a Cloudflare interstitial, twice. What batch 19 adds instead is the holdings layer that makes document delivery actionable: OCLC 222208, LCCN 77502052, ISBN-10 0901908053, LC class NA2545.P5 D5. (4) CLAUSE (5) OF THIS GAP STANDS UNCHANGED and should not be read as weakened: the 1:16 convergence is still ONE document counted once, on Steinfeld''s testimony about Walter, until Walter itself is read. || CORRECTED 2026-09-20: BATCH 19 SECOND CORRECTION, RETRACTING MOST OF ITS FIRST. An adversarial pass over the same batch refuted the clause this gap gained hours earlier, and the retraction is larger than the claim. (1) RETRACTED: clause (2) of my earlier amendment said "Templer 1977 does not resolve to any indexed item, and John A. Templer corpus is stairs end to end ... Four items, fifteen years, no ramp study". FALSE. Templer, John A., Provisions for elderly and handicapped pedestrians, FHWA-RD-79-1/-2/-3, Georgia Tech Pedestrian Research Laboratory, is substantial RAMP research: Volume 3 opens Part I with "A Study of Short Ramps", carries 32 gradient-rating tables for manual and electric wheelchair users and cane users, and closes on TABLE 20 "Ramp Gradient Recommendations" over gradients 1:8, 1:10, 1:12 and 1:16. Full text is free on Internet Archive -- the endpoint this same batch used for Walter an hour earlier and never pointed at Templer. Staged as candidate 125. The Crossref query I called a corpus resolution contained the word "stair", so it returned stair papers; that is query shape, which is R14, which the same note invoked against ERIC while exempting itself. (2) THE PRIORITY INFERENCE IS INVERTED, NOT MERELY WEAKENED. I wrote that the footnote scope means "Templer and Walter are not nodes of the 1:12 chain at all" and that the priority of retrieving them drops. Templer TABLE 20 recommends over 1:8, 1:10, 1:12 and 1:16 -- THE SAME FOUR BANDS as Steinfeld Table 13, whose footnote c marks exactly the two Steinfeld did not test. Retrieving Templer is now the strongest available lead on what footnote c means, not a deprioritised one. (3) THE FOOTNOTE-SCOPE READING ITSELF SURVIVES and was confirmed independently on a rendered page image: the marker sits on 1:8 and 1:10 and not on 1:12 or 1:16, and Table 12 confirms the study stepped 1:12, 1:16, 1:20 only. But TWO THINGS BUILT ON IT DO NOT. The footnote reads "Walters, 1971", not "Walter" -- extraction 56 normalised that to Walter and blamed OCR damage, erasing a real internal inconsistency in the report between its footnote and its bibliography. And my inference that "the 1:12 and 1:16 rows rest on Steinfeld own data" over-reads an absent marker: the report own comparison section says "Walter findings for ramps are similar to ours. Both studies found a 1:16 slope for 20 feet to be accessible to at least 95 percent of the wheelchair users", so Walter IS corroboration for the 1:16 row by the report own words -- which is clause (5) of this gap, the clause my amendment said stood unchanged while contradicting it. (4) ALSO CORRECTED: "a cleaner copy of page 57 decides it in one look" -- the copy this project already holds decided it; nobody had looked. And page 57 is the 1-based PDF page; the PRINTED page is 54. A reader with the physical report was sent to the wrong page, and extraction 57 carries the same confusion (loc_section 163 is the PDF page, printed 161). (5) CLAUSE (5) OF THE ORIGINAL GAP STANDS, and now with a second reader: FHWA-RD-79-3 literature review independently describes Walter 1971 adjustable ramp -- 20 feet at 1:8.6 to 1:16, 10 feet at 1:5.5 to 1:10 -- so a retrievable document corroborates Steinfeld account of Walter. That is not Walter itself and does not make the convergence two documents. || CORRECTED 2026-09-25: BATCH 20: FOOTNOTE c RENDERED AND READ, AND THE CHAIN QUESTION ANSWERED AS FAR AS THE PAGE CAN ANSWER IT. (1) THE READING IS CONFIRMED ON A PERSISTED RENDER. Zero-based index 56 of the ED184280 scan, rendered at 200 dpi and attested (batch-20 manifest, 5dd866a236fb5978.p0056.png): superscript c on the 1:8 row (2 ft, 3 in rise) and the 1:10 row (8 ft, 9 in rise) only; none on 1:12 (30 ft run, 30 in rise) or 1:16 (40 ft, 30 in). The footnote reads ''Based on research of others (Templer, 1977 and Walters, 1971).'' (2) A CORRECTION TO THIS GAP''S OWN 2026-09-20 TEXT: it says the scope reading ''was confirmed independently on a rendered page image'' and that ''the copy this project already holds decided it''. No render of index 56 was persisted anywhere before today -- batch 19''s renders of this PDF are indices 55 (Table 12), 162 and 167-169 (ls retrieval-log/*/5dd866a236fb5978.p*). The reading was right; the claim that a render stood behind it was not, until now. (3) WHAT IT SETTLES: REF-01005 does not cite Templer or Walter for its 1:12 or 1:16 band. Footnote c is not a warrant for 1:12. (4) WHAT IT ADDS, AND IT CUTS BOTH WAYS: the two footnote-c rows reproduce EXACTLY the run and rise of two test ramps in Templer''s FHWA short-ramp study (REF-01008, admitted this batch) -- ramp 9 (1:8, 2 ft, 3 in curb) and ramp 6 (8 ft, 9 in curb, i.e. 1:10.67). That is consistent with footnote c''s Templer being the Georgia Tech ramp work, tested August-November 1976. But ramp 6 was UNACCEPTABLE to manual wheelchair users in ascent in Templer''s own data (58 percent against his ~80 percent line, extraction 66), and his Table 20 recommends 1:10 only up to a 6 in curb (extraction 61): Table 13''s 1:10 band is more permissive than the study its footnote appears to rest on. (5) WHAT IT DOES NOT SETTLE: which document ''Templer, 1977'' is. There are now three candidates and none is chosen -- the 1974 Columbia stairs dissertation REF-01005''s bibliography lists; the FHWA ramp study (REF-01008, reported May 1980); and a forthcoming Templer book, ''Stairs and Ramps'' (Dowden, Hutchinson and Ross), which NBS IR 78-1554 cites six times (read this batch, candidate 117 rehomed). Candidate 115 stays PENDING. (6) TEMPLER BEARS ON 1:12 INDEPENDENTLY, AND ONLY FOR SHORT RISES: Table 20 recommends 1:12 up to a 9 in curb (extraction 62), and 1:12 over a 6 in rise and 6 ft run was acceptable to every manual wheelchair user in ascent (extraction 65). That does not contradict REF-01005''s 1:12 failures over a longer run, because the parameter is length- and rise-conditioned (extraction 63). Templer is evidence ON 1:12; he is not a node OF REF-01005''s 1:12 warrant. (7) WALTER: exhausted under the 2026-09-25 owner ruling and not queued for anyone. REF-01008 gives a second, independent account of Walter''s recommendations (extraction 64: 1:16 over 20 ft for self-propelled wheelchairs) -- corroboration of the REPORT of Walter, so clause (5) stands: Walter is counted once, and only as reported. || CORRECTED 2026-09-25: SECOND BATCH-20 CORRECTION: AN INDEPENDENT ADVERSARIAL PASS SUSTAINED FIVE FAULTS IN THE BATCH-20 NOTE ABOVE. (A) CLAUSE (2) CORRECTED A TRUE STATEMENT INTO A FALSE ONE. Batch 19''s independent adversarial subagent DID render index 56 -- a full page and two crops, in its scratchpad -- and read them (transcripts/harness_ca1ae452/subagents/2026-09-20T03-41-13_other_aaddd48c.jsonl, on main). Batch 20 checked with ls retrieval-log/*/5dd866a236fb5978.p*, which lists only PERSISTED renders and could not see a scratchpad file. Correct form: no render was PERSISTED before batch 20; the 2026-09-20 statement that the reading was confirmed on a rendered page image was true. (B) CLAUSE (3) OVERSTATES. Footnote c does not MARK the 1:12 or 1:16 rows, as the render shows, but REF-01005 separately cites Walter as corroboration for 1:16 over 20 ft on its page 163 (extraction 54: ''Walter findings for ramps are similar to ours'') -- this gap''s own clause (5). Footnote c is not a warrant for 1:12; Walter is a corroborating node for 1:16. (C) CLAUSE (4)''s ''MORE PERMISSIVE'' HOLDS ONLY AGAINST REF-01008''s OWN DATA -- ramp 6''s manual-wheelchair ascent result and Table 20, which stops 1:10 at a 6-in curb -- and REF-01008 is dated May 1980, after REF-01005. Against footnote c''s other warrant, Walter as REF-01008 reports him (1:9 over 10 ft; extraction 64), Table 13''s 1:10 band over 8 ft is STRICTER. And the test was applied to one footnote-c row only: REF-01008''s Conclusions say ''Ramps 6 and 9 were found to be unacceptable to one group, either for ascent or for descent, respectively'', and Table 19 row g marks ramp 9 -- the geometry of Table 13''s 1:8 row -- not acceptable in descent to people with walking difficulties (extractions 60, 66). (D) CLAUSE (6) RESTS ON AN UNTESTED CELL AND A HAND COUNT. Table 20''s 1:12-to-a-9-in-curb (extraction 62), like its 1:10-to-a-6-in-curb (61), was never tested, and both lie on the unacceptable side of the report''s own Table 3 heavy line for manual-wheelchair ascent; both rows are now root_type committee_assertion, and ''interpolation'' was batch 20''s word, not the source''s. The length-conditioning clause (6) leans on was called ''the fourth independent statement'' in extraction 63''s notes; that count took REF-01002 (abstract only; GAP-016) and REF-01003 (path slopes; GAP-033) as support. Listed honestly: MEASURED on ramps by REF-01008 only (curb ramps, rises 3-9 in, extractions 63 and 65-66, and its Part II field ramps at about 1:12); STATED as a mechanism by REF-00996 (T5, no measurement); REF-01002 and REF-01003 bear on it only once GAP-016 and GAP-033 are answered. (E) CLAUSE (7)''s ''second, independent account'' of Walter is not fully independent: REF-01008 mentions a study underway at Syracuse University, most likely REF-01005''s, and REF-01005 cites Templer. Walter stays counted once and only as reported. ALSO: candidate 117''s typed suggested_slug now names the stairs slug (it still named this gap''s slug when clause (5) said ''rehomed''), and a second REF-01005 row now carries footnote c verbatim, ''Walters'' included, beside extraction 56. Commit c3cca9b1''s message repeats clauses (2) and (4) unqualified; it cannot be rewritten, and this is its correction.', "updated_at" = '2026-09-25 06:10' WHERE "gap_id" = 'GAP-037';

