INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (67, 'REF-01005', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'US', NULL, 'qualitative', 'warrant scoped to the 1:8 and 1:10 bands only', NULL, 'Based on research of others (Templer, 1977 and Walters, 1971).', 'Table 13: Maximum Lengths and Slopes for Rampways -- footnote c', NULL, 'committee_assertion', 'REF-01005', NULL, NULL, NULL, NULL, NULL, 0, 'retrieval-log/session_2026-09-18-research-batch-18-archive-route-ramp-threshold/5dd866a236fb5978.pdf', 'page', NULL, NULL, '57', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'one-based PDF page 57 = zero-based index 56 (the convention extraction 56 uses; the printed folio is damaged on the scan); rendered in batch 20 as 5dd866a236fb5978.p0056.png', 're-read', 'reviewed', NULL, 'WRITTEN AS A SECOND ROW BESIDE EXTRACTION 56, NOT AN EDIT OF IT (D-0168; independent adversarial pass, finding #11). Extraction 56''s claim_text normalises the page''s ''Walters'' to ''Walter'' -- a transcription that corrects its source and so cannot be audited against it. This row carries the page''s own words. THE WALTER IDENTITY IS A HYPOTHESIS, STATED HERE AND NOT IN THE QUOTE: ''Walters, 1971'' is read as Felix Walter''s 1971 Disabled Living Foundation study (candidate 109, now EXHAUSTED) because REF-01005''s bibliography lists Walter, 1971 and its page 163 speaks of ''Walter findings for ramps'' (extraction 54); nothing on this page says so. The only ''Walters'' in REF-01008''s text is a research assistant in its credits, not a cited work. SCOPE, from the render: the superscript c sits on the 1:8 row (2 ft run, 3 in rise) and the 1:10 row (8 ft run, 9 in rise) only. [VERBATIM-EXEMPT: RENDER-READ; TEXT LAYER UNDECODABLE. retrieval_log cannot decode the scanned ED184280 PDF (5dd866a236fb5978.pdf), whose pypdf text at zero-based index 56 reads ''cBased on research of others (Templer, 1977 and-WaJter$, 1971).''. This claim_text is transcribed letter for letter from the batch-20 render 5dd866a236fb5978.p0056.png (200 dpi, manifest-attested), and keeps the page''s ''Walters''.]', '2026-09-25 06:10', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 06:10', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', 'claim', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (68, 'REF-01008', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'US', 'field-built single conventional curb ramp, slope approximately 1 in 12 (8.33 percent), with a lip of about 1/4 in at the street; Sioux City, Iowa; wheelchair users in the special-group evaluation', 'qualitative', 'no difficulty with the slope, in either direction', NULL, 'Eleven test subjects used the ramp to enter and leave the street. None appeared to have difficulty with the slope of the ramp, in either direction.', 'Part II, Countermeasure No. 8 (Single Conventional Ramp) -- Evaluation Results; Wheelchair Group', NULL, 'measurement_primary', 'REF-01008', NULL, 'field_observation', NULL, 'Eleven wheelchair users; chair types not stated.', NULL, 0, 'retrieval-log/session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa/db21e48738335d82.pdf', 'page', NULL, NULL, '205', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'printed pp.204-205 = zero-based indices 223-224, both rendered (db21e48738335d82.p0223.png, .p0224.png); the slope is stated on p.204 and the quoted sentences are on p.205', 'full-read', 'verified', NULL, 'FIELD DATA THE BATCH-20 ADMISSION LEFT OUT (independent adversarial pass, finding #20). REF-01008 is not only a laboratory study: Part II built countermeasures in real cities and had special groups use them. At a single conventional curb ramp in Sioux City with ''a slope of approximately 1 in 12 (8.33 percent)'', eleven wheelchair users used it in both directions and ''None appeared to have difficulty with the slope of the ramp''. WHAT LIMITS IT: the judgment is an observer''s (''appeared''); the curb height and run are not given in this passage; the chair types are not given. WHAT ELSE THE SAME TEST FOUND: a construction lip of about a quarter inch ''caused difficulty to three of the 11 subjects''; one subject chose not to use the ramp at all; on 14 of 20 entries into the street the wheelchair users'' path took them beyond the limits of the crosswalk, which the report attributes to the speed gained descending the ramp. Summary finding 2: ''All of the wheelchair users were able to use the ramp''. A short field ramp at about 1:12 is consistent with the laboratory finding that steeper ramps are acceptable if short (extraction 63); it says nothing about longer runs. Owner ruling 2026-09-18: pre-1990 work is historical grounding, not a current anchor.', '2026-09-25 06:10', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 06:10', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', 'finding', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (69, 'REF-01008', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'US', 'field-built double conventional curb ramps ''sloped, at a 1:12 ratio (8.33 percent)'', exposed pebble-aggregate surface; Baltimore, Maryland, beside a community and recreation center for the elderly', 'qualitative', 'the slopes gave no difficulty; the surface did', NULL, 'The ramp slopes themselves appeared to give no difficulty to the wheelchair users.', 'Part II, Countermeasure No. 9 (Double Conventional Ramp) -- Evaluation Results; Wheelchair Group; Table 124', NULL, 'measurement_primary', 'REF-01008', NULL, 'field_observation', NULL, 'Thirteen wheelchair users (the columns of Table 124); at least one used a motorized chair.', NULL, 0, 'retrieval-log/session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa/db21e48738335d82.pdf', 'page', NULL, NULL, '227', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'printed p.227 = zero-based index 246, rendered (db21e48738335d82.p0246.png); the 1:12 slope is stated on printed p.225 (index 244, text layer only)', 'full-read', 'verified', NULL, 'FIELD DATA, SECOND SITE (independent adversarial pass, finding #20). Table 124 gives each of thirteen wheelchair users'' difficulty factor entering and leaving the street by each ramp; the four means are 2.08 to 2.84, on the four-point scale the report defines for its wheelchair evaluations (1 ''equivalent to maneuvering a level surface with no perceptible change in speed'', 4 ''could negotiate only with the greatest difficulty, if at all''). The report attributes the difficulty to the SURFACE, not the slope: ''the pebble textured surface did cause substantial problems, because of its roughness and because of some loose material on the ramp surface''; three narratives describe chairs jamming on it, one user needing assistance to complete the ascent. Summary finding 15: ''The wheelchair users had no difficulty in using the ramps except for the surface finish.'' WHAT LIMITS IT: observer-judged; curb height and run not given in this passage; the slope-versus-surface attribution is the authors''. Owner ruling 2026-09-18: pre-1990 work is historical grounding, not a current anchor.', '2026-09-25 06:10', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 06:10', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', 'finding', NULL);
UPDATE "source_value_extractions" SET "notes" = 'ABSENT IS THE FINDING, AND THE SOURCE SAYS WHY IT IS ABSENT. The largest accessibility audit in this corpus -- every public primary care facility in Brazil -- asks whether a ramp EXISTS and never what gradient it has. The authors state the reason in their introduction: ''Many of these tools are complex, requiring measurement of slopes of ramps and widths of doors, and so on. As a consequence, few large-scale accessibility audits have been conducted''. So the omission is a design choice made for scale, and it generalises: an audit can be national OR measure gradient, and this one chose national. RESULT ON THE ITEM (Table 3 and Results text): ''an access ramp (44%)'' and ''a handrail at the entrance (8%)'', better in the richer South/Southeast and in larger municipalities. WHAT THIS ROW MUST NOT BE READ AS: evidence that 44 percent of Brazilian primary care facilities have a USABLE ramp. A binary presence item cannot distinguish a 1:20 ramp from a 1:6 one, and REF-01005 measured that at 1:12 almost half of wheelchair users could not complete the run. It bears on parameter 3 only as a limit on what presence-counts can say. The authors also record that each feature ''was scored as yes or no, yet there may be variation in accessibility''. || 2026-09-25 extraction_status CONFIRMED absent-confirmed (CORRECTION, SAME BATCH, BY ADVERSARIAL SELF-PASS. This row''s notes say ''THE SOURCE SAYS WHY IT IS ABSENT'' and that ''the omission is a design choice made for scale''. THE SOURCE DOES NOT SAY THAT. Its introduction gives a GENERAL reason large audits are rare -- tools that require ''measurement of slopes of ramps and widths of doors'' are complex, ''As a consequence, few large-scale accessibility audits have been conducted'' -- and it analyses a Ministry of Health census it did not design (PMAQ-AB, secondary data). Nothing in it states why PMAQ-AB''s instrument asks about ramp presence and not gradient. What stands: the item is presence-only, so the row is correctly ABSENT on parameter 3, and the authors do connect slope measurement to audit complexity in general. What is withdrawn: the claim that this source explains THIS instrument''s omission. The status is unchanged; only the reading is corrected.) || 2026-09-25 extraction_status CONFIRMED absent-confirmed (Commit c3cca9b1''s message repeats the claim this row''s A1 correction withdrew -- that the paper ''says why (slope measurement is what keeps audits small)''. A commit message cannot be rewritten, so the correction above stands for it too (independent adversarial pass, finding #17). And R13 for this source is now PARTIAL by owner ruling 2026-09-25, not the PROXY the same message states.)', "updated_at" = '2026-09-25 06:10' WHERE "extraction_id" = 59;
UPDATE "source_value_extractions" SET "notes" = 'TABLE 20 AS RENDERED: columns are ''Gradients Steeper Than 1:8'', 1:8, 1:10, 1:12, 1:16 under ''Maximum Gradient*''; for curb heights not exceeding 3 in (7.62 cm) the row reads X O O O O (X = Not Recommended, O = Recommended), so the steepest recommended gradient at this height is 1:8. Footnote: ''*Whenever possible slopes less than the maximum should be employed.'' THE RECOMMENDATION IS RISE-CONDITIONED, and that is the finding: the report''s own conclusion is ''steeper ramps are acceptable if they are short''. WHAT WAS AND WAS NOT TESTED AT THIS CELL: the only curb height at which 1:8 is recommended; ramp 9 (1:8, 2 ft, 3 in) was tested and acceptable to manual wheelchair users in ascent (95 percent rating 1 or 2). Acceptability criterion (printed p.14): ''a ramp is considered to be acceptable if about 80% of the subjects rated the ramp as 1 or 2'' on a four-point difficulty scale. Owner ruling 2026-09-18: pre-1990 work is historical grounding, not a current anchor -- T3 grey, cannot lift parameter 3 off proxy. [VERBATIM-EXEMPT: TABLE CELLS, NOT A SENTENCE. The only text layer that can be checked (the Internet Archive DjVuTXT, 639e73bd17c02f7f.txt, around the line reading Table 20 Ramp Gradient Recommendations) serialises the table COLUMN BY COLUMN and reads every O mark as the digit 0, so no row of Table 20 exists as a contiguous string in any artefact. This claim_text is the row transcribed from the RENDERED page (db21e48738335d82.p0053.png, printed page 34, zero-based index 53), and the column-wise text layer agrees with it cell for cell. The sentence introducing the table verifies verbatim: Based on these findings, Table 20 shows recommendations for maximum acceptable gradients for three different curb heights.] || 2026-09-25 extraction_status SET verified -> reviewed (Written as ''verified'' minutes earlier in the same batch; corrected before emission. This row''s claim_text is a TRANSCRIPTION of table cells read off a rendered page and carries a VERBATIM-EXEMPT warrant, so nothing byte-checks it. The corpus''s other exempt transcriptions (REF-01005, extractions 52-57) are ''reviewed'', and ''verified'' is kept here for rows whose claim_text verifies byte-for-byte against a persisted artefact (63, 64).) || 2026-09-25 extraction_status CONFIRMED reviewed (THE NOTES ABOVE GIVE ONLY RAMP 9''s FAVOURABLE FIGURE (independent adversarial pass, finding #4). REF-01008''s Conclusions (printed p.33, index 52, rendered): ''Ramps 6 and 9 were found to be unacceptable to one group, either for ascent or for descent, respectively''. Table 19 row g marks ramp 9 (1:8, 2 ft, 3 in) not acceptable in DESCENT to people with walking difficulties, and ramp 11 -- the same geometry with a half-inch lip -- not acceptable in either direction for that group. MOB includes people who walk with difficulty. The 95 percent in the notes above is the manual-wheelchair ASCENT figure only; Table 20 recommends 1:8 up to a 3-in curb over that group''s result. ALSO CORRECTED: the batch-20 status note on this row says rows 63 and 64 keep ''verified'' because their claim_text ''verifies byte-for-byte'' against a persisted artefact. It verifies under retrieval_log''s NORMALISED match (letters and digits only), not byte-for-byte: the DjVu text doubles every space, and at extraction 64 reads ''recommended— for self- propelled''.)', "updated_at" = '2026-09-25 06:10' WHERE "extraction_id" = 60;
